     1	import type {AddressInfo} from 'node:net';
     2	import {WebSocket} from 'ws';
     3	import type {Express} from 'express';
     4	import {createServer} from './createServer.js';
     5	import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
     6	import {answeringOrchestrator} from './wsTestSupport.js';
     7	import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
     8	import type {SessionCursor, SessionListOptions, SessionStore, SessionSummary} from '../types/sessionStore.js';
     9	import {setLogger} from '../shared/logger.js';
    10	
    11	// Real upgrades over a real socket: what the list_sessions frame answers is the contract, and no double can observe it.
    12	
    13	interface Frame {
    14	  type: string;
    15	  sessionId?: string;
    16	  sessions?: Array<{sessionId: string; createdAt: string; updatedAt: string; entryCount: number}>;
    17	  code?: string;
    18	  message?: string;
    19	}
    20	
    21	const servers: Array<ReturnType<typeof createServer>> = [];
    22	const clients: WebSocket[] = [];
    23	const logLines: Array<{level: string; category: string; message: string; fields?: Record<string, unknown>}> = [];
    24	
    25	const eventually = async (check: () => boolean): Promise<void> => {
    26	  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
    27	};
    28	
    29	beforeEach(() => {
    30	  logLines.length = 0;
    31	  const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
    32	    void logLines.push({level, category, message, fields});
    33	  setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
    34	});
    35	
    36	afterEach(async () => {
    37	  for (const client of clients.splice(0)) client.terminate();
    38	  for (const hal of servers.splice(0)) {
    39	    const {wss} = hal;
    40	    await eventually(() => wss.clients.size === 0);
    41	    await hal.stop();
    42	  }
    43	  setLogger();
    44	});
    45	
    46	const startEngine = async (store: SessionStore, userId: string | number = 'u1') => {
    47	  const hal = createServer({
    48	    app: (() => undefined) as unknown as Express,
    49	    wsAuth: async () => ({id: userId}),
    50	    sessionStore: store,
    51	    orchestrator: answeringOrchestrator,
    52	  });
    53	  await hal.start(0);
    54	  servers.push(hal);
    55	  const {port} = hal.server.address() as AddressInfo;
    56	  return `ws://127.0.0.1:${port}/hal/ws`;
    57	};
    58	
    59	const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
    60	  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
    61	  clients.push(client);
    62	  const frames: Frame[] = [];
    63	  let connected: Frame = {type: ''};
    64	  await new Promise<void>(resolve => {
    65	    client.on('message', raw => {
    66	      const frame = JSON.parse(String(raw)) as Frame;
    67	      if (frame.type === 'connected') {
    68	        connected = frame;
    69	        client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
    70	        client.send(JSON.stringify({type: 'ping', timestamp: 1}));
    71	        return;
    72	      }
    73	      if (frame.type === 'pong') {
    74	        resolve();
    75	        return;
    76	      }
    77	      frames.push(frame);
    78	    });
    79	  });
    80	  return {connected, frames};
    81	};
    82	
    83	// A store with only the five required members, so listFor can be omitted, recorded or made to throw.
    84	const delegatingTo = (inner: InMemorySessionStore): SessionStore => ({
    85	  create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
    86	  get: sessionId => inner.get(sessionId),
    87	  delete: sessionId => inner.delete(sessionId),
    88	  count: () => inner.count(),
    89	  clear: () => inner.clear(),
    90	});
    91	
    92	describe('listing conversations over the WebSocket protocol', () => {
    93	  it('answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId', async () => {
    94	    const inner = new InMemorySessionStore();
    95	    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    96	    const summaries: SessionSummary[] = [
    97	      {
    98	        sessionId: 's2',
    99	        createdAt: new Date('2026-01-01T00:00:00.000Z'),
   100	        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
   101	        entryCount: 4,
   102	      },
   103	    ];
   104	    const store: SessionStore = {
   105	      ...delegatingTo(inner),
   106	      listFor: (userId, options) => {
   107	        seen.push({userId, options});
   108	        return summaries;
   109	      },
   110	    };
   111	    const url = await startEngine(store, 'u1');
   112	    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
   113	
   114	    const {frames} = await askAfterConnect(url, {type: 'list_sessions', limit: 10, before, userId: 'u2'});
   115	
   116	    expect({seen, frames}).toEqual({
   117	      seen: [{userId: 'u1', options: {limit: 10, before}}],
   118	      frames: [
   119	        {
   120	          type: 'session_list',
   121	          sessions: [
   122	            {
   123	              sessionId: 's2',
   124	              createdAt: '2026-01-01T00:00:00.000Z',
   125	              updatedAt: '2026-01-01T00:02:00.000Z',
   126	              entryCount: 4,
   127	            },
   128	          ],
   129	        },
   130	      ],
   131	    });
   132	  });
   133	
   134	  it('answers an empty session_list when the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws', async () => {
   135	    const inner = new InMemorySessionStore();
   136	    const withoutList = await startEngine(delegatingTo(inner));
   137	    const failingList = await startEngine({
   138	      ...delegatingTo(inner),
   139	      listFor: () => Promise.reject(new Error('database offline')),
   140	    });
   141	
   142	    const unimplemented = await askAfterConnect(withoutList, {type: 'list_sessions'});
   143	    const failed = await askAfterConnect(failingList, {type: 'list_sessions'});
   144	
   145	    expect({
   146	      unimplemented: unimplemented.frames,
   147	      failed: failed.frames.map(frame => ({type: frame.type, code: frame.code})),
   148	      logged: logLines.filter(line => line.level === 'error' && line.category === 'ws'),
   149	    }).toEqual({
   150	      unimplemented: [{type: 'session_list', sessions: []}],
   151	      failed: [{type: 'error', code: 'SERVER_ERROR'}],
   152	      logged: [
   153	        {
   154	          level: 'error',
   155	          category: 'ws',
   156	          message: expect.any(String),
   157	          fields: expect.objectContaining({userId: 'u1', error: 'database offline'}),
   158	        },
   159	      ],
   160	    });
   161	  });
   162	
   163	  it('accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor', async () => {
   164	    const inner = new InMemorySessionStore();
   165	    let calls = 0;
   166	    const store: SessionStore = {
   167	      ...delegatingTo(inner),
   168	      listFor: () => {
   169	        calls += 1;
   170	        return [];
   171	      },
   172	    };
   173	    const url = await startEngine(store);
   174	    const badFrames = [
   175	      {type: 'list_sessions', limit: 'ten'},
   176	      {type: 'list_sessions', limit: -1},
   177	      {type: 'list_sessions', limit: 1.5},
   178	      {type: 'list_sessions', before: 'not-an-object'},
   179	      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
   180	      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
   181	      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
   182	      {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
   183	    ];
   184	
   185	    const codes: Array<string | undefined> = [];
   186	    for (const bad of badFrames) {
   187	      const {frames} = await askAfterConnect(url, bad);
   188	      codes.push(frames[0]?.code);
   189	    }
   190	    const {frames: accepted} = await askAfterConnect(url, {type: 'list_sessions'});
   191	
   192	    expect({codes, accepted, calls}).toEqual({
   193	      codes: Array(badFrames.length).fill('INVALID_MESSAGE'),
   194	      accepted: [{type: 'session_list', sessions: []}],
   195	      calls: 1,
   196	    });
   197	  });
   198	});
