     1	import {WebSocket} from 'ws';
     2	import type {SessionEntry} from '../../types/session.js';
     3	import type {ChatSession} from '../../types/session.js';
     4	import type {SessionStore} from '../../types/sessionStore.js';
     5	import {ErrorCodes} from '../../types/messages.js';
     6	import type {ListSessionsMessage, OutgoingMessage} from '../../types/messages.js';
     7	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
     8	import {validateMessage} from './validation.js';
     9	import type {ValidationResult} from './validation.js';
    10	import {PerSessionLock} from '../../shared/perSessionLock.js';
    11	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
    12	import {AIError} from '../../types/ai.js';
    13	import type {MessageChunk} from '../../types/ai.js';
    14	import {
    15	  createUserEntry,
    16	  createAssistantEntry,
    17	  createThinkingEntry,
    18	  createToolEntry,
    19	} from '../../orchestration/entryFactories.js';
    20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
    21	import {
    22	  sendJson,
    23	  sendUpsert,
    24	  sendDelta,
    25	  sendCommit,
    26	  sendSkip,
    27	  sendError,
    28	  sendStreamEnd,
    29	  sendSessionList,
    30	} from './sender.js';
    31	import {log} from '../../shared/logger.js';
    32	
    33	interface StreamState {
    34	  thinkingIndex: number | null;
    35	  assistantIndex: number | null;
    36	  suppressOutput: boolean;
    37	  sentAssistantIndices: number[];
    38	}
    39	
    40	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
    41	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
    42	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
    43	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
    44	  const lock = new PerSessionLock();
    45	  return function handleMessage(
    46	    ws: WebSocket,
    47	    session: ChatSession,
    48	    rawMessage: unknown,
    49	    signal?: AbortSignal
    50	  ): Promise<void> {
    51	    const validation = validateMessage(rawMessage);
    52	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
    53	    if (isUserMessageFrame(rawMessage)) {
    54	      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
    55	    }
    56	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
    57	    return wsErrorHandler(ws, () => answerFrame(ws, session, validation, sessionStore));
    58	  };
    59	}
    60	
    61	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
    62	async function answerInTurn(
    63	  ws: WebSocket,
    64	  session: ChatSession,
    65	  orchestrator: ChatOrchestrator,
    66	  validation: ValidationResult,
    67	  signal: AbortSignal | undefined
    68	): Promise<void> {
    69	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
    70	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
    71	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
    72	    return;
    73	  }
    74	  const startedAt = Date.now();
    75	  try {
    76	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
    77	  } finally {
    78	    endTurn(ws, session, signal, startedAt);
    79	  }
    80	}
    81	
    82	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
    83	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
    84	  if (signal?.aborted) {
    85	    log.info('message', 'turn abandoned: its socket closed', {
    86	      sessionId: session.sessionId,
    87	      elapsedMs: Date.now() - startedAt,
    88	    });
    89	    return;
    90	  }
